<?php
declare(strict_types=1);
function assertOfferProject(bool$c,string$m):void{if(!$c)throw new RuntimeException($m);}
$sql=(string)file_get_contents(__DIR__.'/../Database/add_devis_offer_project_classification.sql');foreach(['devis_offer_project_settings','devis_offer_classifications','modifier_classement_devis',"'PRINCIPAL', 'TS'",'uq_one_principal_per_offer']as$n)assertOfferProject(str_contains($sql,$n),'Missing schema element '.$n);assertOfferProject(!preg_match('/ALTER TABLE\s+devis_banamur/i',$sql),'Legacy devis table must stay unchanged.');
$service=(string)file_get_contents(__DIR__.'/../services/DevisOfferProjectService.php');assertOfferProject((bool)preg_match("/\['PRINCIPAL',\s*'TS'\]/",$service),'Only Principal/TS types allowed.');assertOfferProject(str_contains($service,'demoteOtherPrincipal'),'Single principal enforcement missing.');assertOfferProject(str_contains($service,'Le devis doit être rattaché à un projet'),'Project requirement missing.');
$create=(string)file_get_contents(__DIR__.'/../request/generate_devis.php');assertOfferProject(str_contains($create,'DevisOfferProjectController'),'Creation endpoint must delegate to controller.');foreach(['NEW_PROJECT','TS','Ce projet doit d’abord posséder un devis principal classé.','PRINCIPAL']as$n)assertOfferProject(str_contains($service,$n),'Creation service missing '.$n);
$controller=(string)file_get_contents(__DIR__.'/../controllers/DevisOfferProjectController.php');assertOfferProject(str_contains($controller,'DevisOfferProjectMigrationService'),'Controller must ensure automatic schema.');assertOfferProject(str_contains($controller,'DevisOfferProjectService'),'Controller must delegate business logic to service.');
$migration=(string)file_get_contents(__DIR__.'/../services/DevisOfferProjectMigrationService.php');assertOfferProject(str_contains($migration,'columnExists'),'Existing schema upgrade must be idempotent.');assertOfferProject(str_contains($migration,'indexExists'),'Existing indexes must be checked.');assertOfferProject(str_contains($migration,'assertNoDuplicatePrincipals'),'Migration must reject ambiguous principal data.');
$endpoint=(string)file_get_contents(__DIR__.'/../request/classer_devis_offre.php');assertOfferProject(str_contains($endpoint,'requirePageAccess'),'Classification permission missing.');assertOfferProject(str_contains($endpoint,'hash_equals'),'Classification CSRF missing.');
$list=(string)file_get_contents(__DIR__.'/../partials/devis_offer_groups.php');assertOfferProject(str_contains($list,'PROJET'),'Project grouping view missing.');
echo"DevisOfferProjectClassificationTest: OK\n";
